const categories=[['🎮','Jogos','Digitais e físicos','#ff641e','Jogos'],['🎧','Acessórios','Headsets, mouses e mais','#16bfff','Acessórios'],['🕹️','Consoles','PlayStation, Xbox e Nintendo','#ff641e','Consoles'],['⚙️','Serviços','Manutenção e configuração','#16bfff','Serviços'],['🏷️','Ofertas','Descontos especiais','#ff641e','Ofertas']];
const state={route:'home',filter:'Todos',cart:JSON.parse(localStorage.getItem('blackout-cart')||'{}'),favorites:JSON.parse(localStorage.getItem('blackout-favorites')||'[]'),selected:null,checkoutStep:1};
const app=document.querySelector('#app');
const money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const save=()=>{localStorage.setItem('blackout-cart',JSON.stringify(state.cart));localStorage.setItem('blackout-favorites',JSON.stringify(state.favorites));updateCart()};
const updateCart=()=>document.querySelector('.cart-count').textContent=Object.values(state.cart).reduce((a,b)=>a+b,0);
const toast=msg=>{const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)};
function card(p){return `<article class="product-card"><span class="badge">-${p.discount}%</span><button class="favorite ${state.favorites.includes(p.id)?'on':''}" data-favorite="${p.id}" aria-label="Favoritar">${state.favorites.includes(p.id)?'♥':'♡'}</button><div class="product-visual" style="--glow:${p.glow}" data-product="${p.id}">${p.icon}</div><div class="product-info"><small>${p.platform}</small><h3>${p.name}</h3><div class="price">${money(p.price)}</div><div class="old-price">${money(p.old)}</div><div class="card-actions"><button class="buy" data-add="${p.id}">Comprar</button><button data-product="${p.id}" aria-label="Ver detalhes">›</button></div></div></article>`}
function home(){return `<section class="hero hero-art" aria-label="Destaques BLACKOUT"><button class="hero-hotspot hotspot-cta" data-route="catalog" aria-label="Confira agora: abrir catálogo">Confira agora</button><button class="hero-hotspot hotspot-games" data-category="Jogos" aria-label="Abrir Jogos">Jogos</button><button class="hero-hotspot hotspot-accessories" data-category="Acessórios" aria-label="Abrir Acessórios">Acessórios</button><button class="hero-hotspot hotspot-consoles" data-category="Consoles" aria-label="Abrir Consoles">Consoles</button><button class="hero-hotspot hotspot-services" data-category="Serviços" aria-label="Abrir Serviços">Serviços</button><button class="hero-hotspot hotspot-offers" data-category="Ofertas" aria-label="Abrir Ofertas">Ofertas</button></section>
<section class="section"><div class="category-grid">${categories.map(c=>`<button class="category-card" style="--tone:${c[3]}" data-category="${c[4]}"><span class="cat-icon">${c[0]}</span><strong>${c[1]}</strong><small>${c[2]}</small></button>`).join('')}</div></section>
<section class="section launch-strip"><div class="launch-art"></div><div class="launch-copy"><span class="eyebrow">Nível máximo desbloqueado</span><h2>LANÇAMENTOS<br>EM JOGOS</h2><p>Os maiores títulos você encontra aqui.</p><button class="secondary" data-category="Jogos">Ver jogos →</button></div></section>
<section class="section"><div class="section-head"><h2><span class="accent">🔥</span> OFERTAS EM DESTAQUE</h2><button class="link-btn" data-route="offers">Ver todas ›</button></div><div class="product-grid">${products.slice(0,4).map(card).join('')}</div></section>`}
function catalog(offers=false){const filters=['Todos','Jogos','Acessórios','Consoles','Hardware','Monitores'];let list=state.filter==='Todos'?products:products.filter(p=>p.category===state.filter);if(offers) list=products.filter(p=>p.discount>=20);return `<div class="page-head"><div><h1 class="page-title">${offers?'OFERTAS BLACKOUT':'CATÁLOGO'}</h1><p class="page-sub">${offers?'Descontos ativos por tempo limitado.':'Encontre seu próximo upgrade.'}</p></div><span>${list.length} itens</span></div>${offers?'':`<div class="filters">${filters.map(f=>`<button class="chip ${state.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>`}<div class="product-grid">${list.map(card).join('')}</div>`}
function product(){const p=products.find(x=>x.id===state.selected)||products[0];setWhats(`Olá! Gostaria de informações sobre ${p.name}.`);return `<button class="link-btn" data-route="catalog">← Voltar ao catálogo</button><section class="detail section"><div class="detail-art">${p.icon}</div><div><span class="eyebrow">${p.brand} • ${p.platform}</span><h1>${p.name}</h1><div class="rating">★★★★★ <small>${p.rating} (128 avaliações)</small></div><p>${p.desc}</p><div class="old-price">${money(p.old)}</div><div class="price">${money(p.price)}</div><p>ou 10x de <strong>${money(p.price/10)}</strong> sem juros</p><p class="stock">● Em estoque — ${p.stock} unidades</p><div class="qty"><button data-qty="-1">−</button><span id="detail-qty">1</span><button data-qty="1">+</button></div><div class="detail-actions"><button class="primary" data-buy-now="${p.id}">Comprar agora</button><button class="secondary" data-add="${p.id}">Adicionar ao carrinho</button></div><div class="tabs"><h2>Descrição e especificações</h2><div class="specs"><span>✓ Garantia de 12 meses</span><span>✓ Nota fiscal</span><span>✓ Produto original</span><span>✓ Envio para todo Brasil</span></div></div></div></section>`}
function cart(){const items=Object.entries(state.cart).map(([id,q])=>({p:products.find(x=>x.id===+id),q})).filter(x=>x.p);const sub=items.reduce((a,x)=>a+x.p.price*x.q,0);return `<div class="page-head"><div><h1 class="page-title">SEU CARRINHO</h1><p class="page-sub">Revise seus itens antes de avançar.</p></div></div>${items.length?`<div class="cart-layout"><div>${items.map(({p,q})=>`<div class="cart-item"><div class="mini-art">${p.icon}</div><div><strong>${p.name}</strong><div class="price">${money(p.price)}</div><div class="qty"><button data-cart-qty="${p.id}:-1">−</button><span>${q}</span><button data-cart-qty="${p.id}:1">+</button></div></div><button class="remove" data-remove="${p.id}">Remover</button></div>`).join('')}</div><aside class="summary"><h2>Resumo</h2><div class="coupon"><input placeholder="Cupom de desconto"><button data-coupon>Aplicar</button></div><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Entrega</span><b>Grátis</b></div><div class="summary-row total"><span>Total</span><span>${money(sub)}</span></div><button class="primary" data-route="checkout" style="width:100%">Finalizar compra</button></aside></div>`:`<div class="empty"><h2>Seu carrinho está vazio</h2><p>Explore o catálogo e prepare seu próximo upgrade.</p><button class="primary" data-route="catalog">Ver catálogo</button></div>`}`}
function checkout(){const steps=['Dados','Endereço','Entrega','Pagamento','Revisão','Confirmado'];return `<div class="page-head"><div><h1 class="page-title">CHECKOUT SEGURO</h1><p class="page-sub">Etapa ${state.checkoutStep} de 6</p></div></div><div class="checkout-steps">${steps.map((s,i)=>`<div class="step ${i+1<=state.checkoutStep?'active':''}">${i+1}. ${s}</div>`).join('')}</div><section class="summary" style="max-width:760px;margin:auto;position:static">${checkoutContent()}<div class="detail-actions" style="margin-top:22px">${state.checkoutStep>1&&state.checkoutStep<6?'<button class="secondary" data-checkout="prev">Voltar</button>':''}${state.checkoutStep<6?`<button class="primary" data-checkout="next">${state.checkoutStep===5?'Confirmar pedido':'Continuar'}</button>`:'<button class="primary" data-route="orders">Acompanhar pedido</button>'}</div></section>`}
function checkoutContent(){if(state.checkoutStep===1)return `<h2>Dados do cliente</h2><div class="form-grid"><div class="form-field"><label>Nome completo</label><input value="Alex Gamer"></div><div class="form-field"><label>E-mail</label><input value="alex@email.com"></div><div class="form-field"><label>Telefone</label><input placeholder="(00) 00000-0000"></div><div class="form-field"><label>CPF</label><input placeholder="000.000.000-00"></div></div>`;if(state.checkoutStep===2)return `<h2>Endereço</h2><div class="form-grid"><div class="form-field"><label>CEP</label><input placeholder="00000-000"></div><div class="form-field"><label>Cidade</label><input></div><div class="form-field"><label>Rua</label><input></div><div class="form-field"><label>Número</label><input></div></div>`;if(state.checkoutStep===3)return `<h2>Como você quer receber?</h2><label class="menu-list"><button>🚚 Entrega expressa <b>Grátis</b></button><button>🏪 Retirada na loja <b>Hoje</b></button></label>`;if(state.checkoutStep===4)return `<h2>Pagamento</h2><div class="menu-list"><button>◈ PIX <b>5% de desconto</b></button><button>▰ Cartão de crédito <b>até 10x</b></button></div>`;if(state.checkoutStep===5)return `<h2>Revise seu pedido</h2><p>Produtos, endereço, entrega e pagamento estão prontos. Ao confirmar, você receberá as atualizações do pedido.</p>`;return `<div class="empty"><h2>✓ Pedido confirmado!</h2><p>Seu pedido #BK-1048 foi recebido. Enviaremos todas as atualizações.</p></div>`}
function servicesView(){setWhats('Olá! Gostaria de solicitar um serviço técnico BLACKOUT.');return `<div class="page-head"><div><h1 class="page-title">SERVIÇOS BLACKOUT</h1><p class="page-sub">Seu setup nas mãos de quem entende.</p></div></div><div class="service-grid">${services.map(s=>`<article class="service-card"><span class="service-icon">${s.icon}</span><h3>${s.name}</h3><p>${s.desc}</p><strong>${s.price}</strong><small style="display:block;color:#8fa0aa;margin:6px 0 16px">Prazo: ${s.time}</small><button class="secondary service-request" data-service="${s.name}">Solicitar serviço</button></article>`).join('')}</div>`}
function orders(){return `<div class="page-head"><div><h1 class="page-title">PEDIDO #BK-1048</h1><p class="page-sub">Previsão de entrega: 18 de setembro</p></div><span class="status-pill">Em preparação</span></div><section class="summary" style="position:static;max-width:700px"><div class="timeline">${[['Pedido recebido','15 set • 10:32'],['Pagamento confirmado','15 set • 10:34'],['Preparando','Seu pedido está sendo separado'],['Enviado','Aguardando'],['Entregue','Aguardando']].map((x,i)=>`<div class="timeline-item ${i<3?'done':''}"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section>`}
function profile(){return `<div class="profile-card"><div class="avatar">👤</div><div><h2 style="margin:0">Alex Gamer</h2><p style="margin:5px 0;color:#91a1ab">alex@email.com</p></div><button class="secondary">Editar</button></div><div class="menu-list"><button data-route="orders">Meus pedidos <span>›</span></button><button data-route="favorites">Meus favoritos <span>›</span></button><button>Meus endereços <span>›</span></button><button>Cupons <span>›</span></button><button>Notificações <span>›</span></button><button>Configurações <span>›</span></button><button data-action="login">Entrar ou criar conta <span>›</span></button></div>`}
function favorites(){const list=products.filter(p=>state.favorites.includes(p.id));return `<div class="page-head"><div><h1 class="page-title">MEUS FAVORITOS</h1><p class="page-sub">Produtos que você guardou.</p></div></div>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:'<div class="empty"><h2>Nenhum favorito ainda</h2><p>Toque no coração dos produtos para guardar aqui.</p></div>'}`}
function admin(){return `<div class="page-head"><div><span class="eyebrow">Área restrita</span><h1 class="page-title">PAINEL BLACKOUT</h1></div><button class="secondary">+ Novo produto</button></div><div class="admin-kpis"><div class="kpi"><small>Faturamento</small><strong>${money(28640)}</strong></div><div class="kpi"><small>Pedidos</small><strong>128</strong></div><div class="kpi"><small>Estoque baixo</small><strong style="color:#ff6a21">7</strong></div><div class="kpi"><small>Serviços</small><strong>18</strong></div></div><div style="overflow:auto"><table class="admin-table"><thead><tr><th>Produto</th><th>Categoria</th><th>Estoque</th><th>Preço</th><th>Status</th></tr></thead><tbody>${products.slice(0,6).map(p=>`<tr><td>${p.name}</td><td>${p.category}</td><td>${p.stock}</td><td>${money(p.price)}</td><td><span class="status-pill">Ativo</span></td></tr>`).join('')}</tbody></table></div>`}
function render(){setWhats('Olá! Gostaria de atendimento na BLACKOUT.');const views={home:home,catalog:()=>catalog(false),offers:()=>catalog(true),product,cart,checkout,services:servicesView,orders,profile,favorites,admin};app.innerHTML=(views[state.route]||home)();document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route));app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});bind()}
function go(route){state.route=route;history.pushState({route},'',`#${route}`);closePanels();render()}
function setWhats(msg){document.querySelector('#whatsapp').href=`https://wa.me/5500000000000?text=${encodeURIComponent(msg)}`}
function closePanels(){document.querySelector('#drawer').classList.remove('open');document.querySelector('#backdrop').classList.remove('open');document.querySelector('#search-panel').classList.remove('open')}
function bind(){document.querySelectorAll('[data-route]').forEach(e=>e.onclick=()=>go(e.dataset.route));document.querySelectorAll('[data-category]').forEach(e=>e.onclick=()=>{const c=e.dataset.category;if(c==='Serviços')go('services');else if(c==='Ofertas')go('offers');else{state.filter=c;go('catalog')}});document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{state.filter=e.dataset.filter;render()});document.querySelectorAll('[data-product]').forEach(e=>e.onclick=()=>{state.selected=+e.dataset.product;go('product')});document.querySelectorAll('[data-add]').forEach(e=>e.onclick=()=>{const id=+e.dataset.add;state.cart[id]=(state.cart[id]||0)+1;save();toast('Produto adicionado ao carrinho')});document.querySelectorAll('[data-buy-now]').forEach(e=>e.onclick=()=>{const id=+e.dataset.buyNow;state.cart[id]=(state.cart[id]||0)+1;save();go('checkout')});document.querySelectorAll('[data-favorite]').forEach(e=>e.onclick=()=>{const id=+e.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render()});document.querySelectorAll('[data-cart-qty]').forEach(e=>e.onclick=()=>{const [id,d]=e.dataset.cartQty.split(':').map(Number);state.cart[id]=(state.cart[id]||0)+d;if(state.cart[id]<=0)delete state.cart[id];save();render()});document.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{delete state.cart[e.dataset.remove];save();render()});document.querySelectorAll('[data-checkout]').forEach(e=>e.onclick=()=>{state.checkoutStep+=e.dataset.checkout==='next'?1:-1;if(state.checkoutStep===6){state.cart={};save()}render()});document.querySelectorAll('.service-request').forEach(e=>e.onclick=()=>window.open(`https://wa.me/5500000000000?text=${encodeURIComponent('Olá! Gostaria de solicitar o serviço: '+e.dataset.service+'.')}`,'_blank'));document.querySelector('[data-coupon]')?.addEventListener('click',()=>toast('Cupom validado para esta demonstração'));document.querySelector('[data-action="login"]')?.addEventListener('click',()=>toast('Login preparado para integração'))}
document.body.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='menu'){document.querySelector('#drawer').classList.add('open');document.querySelector('#backdrop').classList.add('open')}if(a.dataset.action==='close-menu')closePanels();if(a.dataset.action==='search'){document.querySelector('#search-panel').classList.add('open');setTimeout(()=>document.querySelector('#global-search').focus(),50)}if(a.dataset.action==='close-search')closePanels();if(a.dataset.action==='notify')toast('Você está em dia com as novidades')});
document.querySelector('#global-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();const hits=[...products.map(p=>({...p,type:'Produto'})),...services.map((s,i)=>({id:100+i,name:s.name,type:'Serviço'}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,8);document.querySelector('#search-results').innerHTML=q?(hits.length?hits.map(x=>`<div class="search-hit" data-search-id="${x.id}" data-search-type="${x.type}"><span><small>${x.type}</small><br><strong>${x.name}</strong></span><b>›</b></div>`).join(''):'<div class="empty">Nenhum resultado encontrado.</div>'):'';document.querySelectorAll('[data-search-id]').forEach(h=>h.onclick=()=>{if(h.dataset.searchType==='Serviço')go('services');else{state.selected=+h.dataset.searchId;go('product')}})});
window.addEventListener('popstate',e=>{state.route=e.state?.route||location.hash.slice(1)||'home';render()});
state.route=location.hash.slice(1)||'home';updateCart();render();
